mapper.select:
SELECT COALESCE(MAX(sys01_erp_product_cd) = 'A1', false)
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

mapper.sql:
SELECT *
  FROM mkt01_target_company
 WHERE mkt01_company_id = #{companyId}
   AND mkt01_item_type_cd LIKE #{itemTypeCode}

   AND COALESCE(mkt01_unuse_yn,'false') != 'true'

   AND UPPER(CONCAT(mkt01_target_company_nm, mkt01_note)) LIKE UPPER(#{searchText})

mapper.update:
UPDATE mkt01_target_company
   SET mkt01_item_type_cd      = #{r.itemTypeCode}
     , mkt01_target_company_nm = #{r.targetCompanyName}
     , mkt01_addr              = #{r.addr}
     , mkt01_tel               = #{r.tel}
     , mkt01_note              = #{r.note}
     , mkt01_unuse_yn          = CASE WHEN #{r.unuseYn} THEN 'true' ELSE 'false' END
 WHERE mkt01_target_company_id = #{r.targetCompanyId}
   AND mkt01_company_id        = #{companyId}

