  FROM mkt03_history
 WHERE mkt03_target_company_id = #{targetCompanyId}
   AND mkt03_company_id        = #{companyId}

mapper.delete:
DELETE FROM mkt02_manager
 WHERE mkt02_target_company_id = #{targetCompanyId}
   AND mkt02_company_id        = #{companyId}

DELETE FROM mkt05_share
 WHERE mkt05_parent_id  = #{parentId}
   AND mkt05_company_id = #{companyId}

DELETE FROM mkt01_target_company
 WHERE mkt01_target_company_id = #{targetCompanyId}
   AND mkt01_company_id        = #{companyId}

DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}
